import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    balance = [0] * (n + 1)

    for _ in range(m):
        a = int(next(iterator))
        b = int(next(iterator))
        c = int(next(iterator))
        balance[a] -= c
        balance[b] += c

    total_debt = 0
    has_debtors = False
    has_creditors = False

    for i in range(1, n + 1):
        if balance[i] < 0:
            has_debtors = True
            total_debt += -balance[i]
        elif balance[i] > 0:
            has_creditors = True

    if not has_debtors or not has_creditors:
        print(0)
        return

    print(total_debt)

if __name__ == "__main__":
    solve()
